"seq":12,"relation":"authors","after_row":{"id":987303012,"name":"George P. Pelecanos","open_library_id":"OL25882A"},"before_row":null},{"key":{"open_library_id":"OL784428A"},"seq":13,"relation":"authors","after_row":{"id":987303013,"name":"Els Witte","open_library_id":"OL784428A"},"before_row":null},{"key":{"open_library_id":"OL198269A"},"seq":14,"relation":"authors","after_row":{"id":987303014,"name":"Joost Zwagerman","open_library_id":"OL198269A"},"before_row":null},{"key":{"native_identity_key":"nlscale:20261102:ol:OL49488W"},"seq":15,"relation":"works","after_row":{"id":987103001,"title":"Ender''s Game","cover_id":8186454,"author_id":987303001,"work_type":"novel","source_type":"open_library","open_library_id":"OL49488W","first_publish_year":1985,"native_identity_key":"nlscale:20261102:ol:OL49488W"},"before_row":null},{"key":{"open_library_edition_id":"OL26457851M"},"seq":16,"relation":"editions","after_row":{"id":987203001,"title":"Ender''s Game","isbn_10":null,"isbn_13":"9789022568200","work_id":987103001,"cover_id":8186454,"language":"dut","publisher":"Boekerij","publish_date":null,"open_library_edition_id":"OL26457851M"},"before_row":null},{"key":{"work_id":987103001,"language":"nl"},"seq":17,"relation":"catalog_work_descriptions","after_row":{"text":"De aarde bereidt zich voor op een nieuwe oorlog met een buitenaardse beschaving. Bij de opleiding van toekomstige bevelhebbers richt het leger zich op uitzonderlijk begaafde kinderen. Andrew Wiggin, die Ender wordt genoemd, blijkt bijzonder goed in strategische spellen. Zijn training stelt hem echter ook bloot aan eenzaamheid, concurrentie en steeds zwaardere verwachtingen. De roman onderzoekt wat er met een kind gebeurt wanneer volwassenen zijn talent voor militaire doeleinden inzetten.","work_id":987103001,"evidence":[{"note":"Full novel, distinct from current Speaker for the Dead, Xenocide, Ender''s Shadow, Ender in Exile and Shadow of the Hegemon. Publisher confirms military-child premise and original author; library confirms1985 print.","type":"reviewed_identity_and_bibliography","sources":["https://data.bibliotheken.nl/id/nbt/p362787433"],"reference":"new-work-dossier-readings-004.json#2","checked_at":"2026-11-02T17:16:06.000Z"},{"type":"original_substantive_source_review","review":"content-review-001.json","sources":["https://us.macmillan.com/books/9780765394866/endersgame/","https://discover.library.unt.edu/catalog/b1878557","https://openlibrary.org/works/OL49488W","https://data.bibliotheken.nl/id/nbt/p362787433"]},{"type":"explicit_contributor_roles","credits":[],"limitation":"Existing schema has one primary Work author; no synthetic combined-author identity or author merge."},{"type":"cover_front_review","sha256":"427e1911bfa7f06bdfd577d443719975836f187db6fe63c99e241f7b33f5d07b","cover_id":8186454,"reference":"cover-semantic-review-002.json","limitation":"Front title/author and source-edition binding; no barcode or exact printing-year claim."}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://us.macmillan.com/books/9780765394866/endersgame/","reviewed_at":"2026-11-02T17:16:06+00:00","source_name":"Gecontroleerde boek- en catalogusbronnen","source_type":"official_catalog","review_batch":"nl-scale-20261102-004","review_status":"approved","bound_author_id":987303001},"before_row":null},{"key":{"edition_id":987203001},"seq":18,"relation":"catalog_edition_metadata","after_row":{"format":"paperback","work_id":987103001,"evidence":[{"note":"Full novel, distinct from current Speaker for the Dead, Xenocide, Ender''s Shadow, Ender in Exile and Shadow of the Hegemon. Publisher confirms military-child premise and original author; library confirms1985 print.","type":"reviewed_identity_and_bibliography","sources":["https://data.bibliotheken.nl/id/nbt/p362787433"],"reference":"new-work-dossier-readings-004.json#2","checked_at":"2026-11-02T17:16:06.000Z"},{"type":"original_substantive_source_review","review":"content-review-001.json","source