":"nlscale:20261102:ol:OL16796166W"},"before_row":null},{"key":{"open_library_edition_id":"OL28373875M"},"seq":24,"relation":"editions","after_row":{"id":987203003,"title":"Een goede raad","isbn_10":null,"isbn_13":"9789022564301","work_id":987103003,"cover_id":10310623,"language":"dut","publisher":"De Boekerij","publish_date":null,"open_library_edition_id":"OL28373875M"},"before_row":null},{"key":{"work_id":987103003,"language":"nl"},"seq":25,"relation":"catalog_work_descriptions","after_row":{"text":"Het onverwachte overlijden van Barry Fairbrother laat een plaats open in het bestuur van Pagford. Achter het verzorgde aanzien van het Engelse stadje blijken bewoners sterk verdeeld. De strijd om zijn opvolging raakt aan verschillen tussen rijk en arm en aan spanningen binnen gezinnen. Terwijl kandidaten en omstanders hun eigen belangen verdedigen, komen onderlinge verhoudingen onder druk te staan. De roman volgt hoe een lokale verkiezing conflicten zichtbaar maakt die al langer onder de oppervlakte bestaan.","work_id":987103003,"evidence":[{"note":"Exact2012 NL paperback corroborated by two independent bibliographic/retail records despite absent KB match. Adult Pagford novel; neither Harry Potter nor a Cormoran Strike novel.","type":"reviewed_identity_and_bibliography","sources":["https://www.heinen.nl/a/j-k-rowling/een-goede-raad/100001119","https://boekenbase.nl/boek/een-goede-raad-j-k-rowling-9789022564301?from=%2Fauteur%2Fsabine-mutsaers"],"reference":"new-work-dossier-readings-004.json#19","checked_at":"2026-11-02T17:16:06.000Z"},{"type":"original_substantive_source_review","review":"content-review-001.json","sources":["https://www.nl.fnac.be/a8717544/J-K-Rowling-Een-goede-raad-paperback-editie","https://www.heinen.nl/a/j-k-rowling/een-goede-raad/100001119","https://boekenbase.nl/boek/een-goede-raad-j-k-rowling-9789022564301?from=%2Fauteur%2Fsabine-mutsaers","https://openlibrary.org/works/OL16796166W"]},{"type":"explicit_contributor_roles","credits":[{"name":"Tom Hollander","role":"audio performer; not a print coauthor"},{"name":"Carolien Metaal","role":"Dutch translator"},{"name":"Sabine Mutsaers","role":"Dutch translator"}],"limitation":"Existing schema has one primary Work author; no synthetic combined-author identity or author merge."},{"type":"cover_front_review","sha256":"1c8bf7fd8c65e6d95c754a2191fed5407694ea88038f87e6d7fbbd2ee1d0f91b","cover_id":10310623,"reference":"cover-semantic-review-002.json","limitation":"Front title/author and source-edition binding; no barcode or exact printing-year claim."}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://www.nl.fnac.be/a8717544/J-K-Rowling-Een-goede-raad-paperback-editie","reviewed_at":"2026-11-02T17:16:06+00:00","source_name":"Gecontroleerde boek- en catalogusbronnen","source_type":"official_catalog","review_batch":"nl-scale-20261102-004","review_status":"approved","bound_author_id":962300003},"before_row":null},{"key":{"edition_id":987203003},"seq":26,"relation":"catalog_edition_metadata","after_row":{"format":"paperback","work_id":987103003,"evidence":[{"note":"Exact2012 NL paperback corroborated by two independent bibliographic/retail records despite absent KB match. Adult Pagford novel; neither Harry Potter nor a Cormoran Strike novel.","type":"reviewed_identity_and_bibliography","sources":["https://www.heinen.nl/a/j-k-rowling/een-goede-raad/100001119","https://boekenbase.nl/boek/een-goede-raad-j-k-rowling-9789022564301?from=%2Fauteur%2Fsabine-mutsaers"],"reference":"new-work-dossier-readings-004.json#19","checked_at":"2026-11-02T17:16:06.000Z"},{"type":"original_substantive_source_review","review":"content-review-001.json","sources":["https://www.nl.fnac.be/a8717544/J-K-Rowling-Een-goede-raad-paperback-editie","https://www.heinen.nl/a/j-k-rowling/een-goede-raad/100001119","https://boekenbase.nl/boek/een-goede-raad-j-k-rowling-9789022564301?from=%2Fauteur%2Fsabine-mutsaers","https://openlibrary.org/works/OL16796166W"]},{"type":"e