rg/b/id/13137506-M.jpg?default=false","bound_author_id":987303005},"before_row":null},{"key":{"native_identity_key":"nlscale:20261102:ol:OL3899219W"},"seq":39,"relation":"works","after_row":{"id":987103007,"title":"Den skrattande polisen","cover_id":14403489,"author_id":987303004,"work_type":"novel","source_type":"open_library","open_library_id":"OL3899219W","first_publish_year":1968,"native_identity_key":"nlscale:20261102:ol:OL3899219W"},"before_row":null},{"key":{"open_library_edition_id":"OL49228322M"},"seq":40,"relation":"editions","after_row":{"id":987203007,"title":"De lachende politieman","isbn_10":null,"isbn_13":"9789044914399","work_id":987103007,"cover_id":14403489,"language":"dut","publisher":"A W Bruna en zoon","publish_date":null,"open_library_edition_id":"OL49228322M"},"before_row":null},{"key":{"work_id":987103007,"language":"nl"},"seq":41,"relation":"catalog_work_descriptions","after_row":{"text":"Op een regenachtige avond worden negen mensen in een bus in Stockholm doodgeschoten. De aanval lijkt willekeurig, maar een van de slachtoffers is een rechercheur uit het team van Martin Beck. Voor Beck is dat een reden om verder te kijken dan de eerste verklaring van een zinloze massamoord. Wat deed zijn collega in die bus en welke verbinding is er tussen de reizigers? Het onderzoek draait om de achtergrond van een gebeurtenis die aanvankelijk geen herkenbaar motief lijkt te hebben.","work_id":987103007,"evidence":[{"note":"Den skrattande polisen/The Laughing Policeman is a separate Martin Beck novel, not Roseanna or The Fire Engine That Disappeared. Exact KB Dutch ISBN and1968 original agree. Historical claim that the series inspired the earlier Agatha Christie is discarded.","type":"reviewed_identity_and_bibliography","sources":["https://data.bibliotheken.nl/id/nbt/p043966454","https://data.bibliotheken.nl/id/nbt/p425276813","https://data.bibliotheken.nl/id/nbt/p833407988"],"reference":"new-work-dossier-readings-004.json#75","checked_at":"2026-11-02T17:16:06.000Z"},{"type":"original_substantive_source_review","review":"content-review-007.json","sources":["https://www.penguinrandomhouse.com/books/168101/the-laughing-policeman-by-maj-sjowall-and-per-wahloo-with-a-new-introduction-by-jonathan-franzen/paperback/","https://openlibrary.org/works/OL3899219W","https://data.bibliotheken.nl/id/nbt/p043966454","https://data.bibliotheken.nl/id/nbt/p425276813","https://data.bibliotheken.nl/id/nbt/p833407988"]},{"type":"explicit_contributor_roles","credits":[{"name":"Per Wahlöö","role":"joint original author"},{"name":"Jonathan Franzen","role":"later-edition introduction"}],"limitation":"Existing schema has one primary Work author; no synthetic combined-author identity or author merge."},{"type":"cover_front_review","sha256":"76fa5d9aa67604ec4d375e3982a99fd5b2601e3eee3d6c3e0f48a08ae78631df","cover_id":14403489,"reference":"cover-semantic-review-002.json","limitation":"Front title/author and source-edition binding; no barcode or exact printing-year claim."}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://www.penguinrandomhouse.com/books/168101/the-laughing-policeman-by-maj-sjowall-and-per-wahloo-with-a-new-introduction-by-jonathan-franzen/paperback/","reviewed_at":"2026-11-02T17:16:06+00:00","source_name":"Gecontroleerde boek- en catalogusbronnen","source_type":"official_catalog","review_batch":"nl-scale-20261102-004","review_status":"approved","bound_author_id":987303004},"before_row":null},{"key":{"edition_id":987203007},"seq":42,"relation":"catalog_edition_metadata","after_row":{"format":"paperback","work_id":987103007,"evidence":[{"note":"Den skrattande polisen/The Laughing Policeman is a separate Martin Beck novel, not Roseanna or The Fire Engine That Disappeared. Exact KB Dutch ISBN and1968 original agree. Historical claim that the series inspired the earlier Agatha Christie is discarded.","type":"reviewed_identity_and_bibliography","sources":["https://data.bibliotheken.nl/id/nbt/p043966454","https://data.bibliotheken.nl/id/nbt/p425276813","https://data.bibliotheken.nl/id/nbt/p833407988"],"reference":"new-work-dossier-readings-004.json#75","checked_at":"2026-11-02T17:16:06.000Z"},{"type":"original_substantive_source_review","review":"content-review-007.json","sources":["https://www.penguinrandomhouse.com/books/168101/the-laughing-policeman-by-maj-sjowall-and-per-wahloo-with-a-new-introduction-by-jonathan-franzen/paperback/","https://openlibrary.org/works/OL3899219W","https://data.bibliotheken.nl/id/nbt/p043966454","https://data.bibliotheken.nl/id/nbt/p425276813","https://data.bibliotheken.nl/id/nbt/p833407988"]},{"type":"explicit_contributor_roles","credits":[{"name":"Per Wahlöö","role":"joint original author"},{"name":"Jonathan Franzen","role":"later-edition introduction"}],"limitation":"Existing schema has one primary Work author; no synthetic combined-author identity or author merge."},{"type":"cover_front_review","sha256":"76fa5d9aa67604ec4d375e3982a99fd5b2601e3eee3d6c3e0f48a08ae78631df","cover_id":14403489,"reference":"cover-semantic-review-002.json","limitation":"Front title/author and source-edition binding; no barcode or exact printing-year claim."}],"cover_url":"https://covers.openlibrary.org/b/id/14403489-L.jpg?default=false","edition_id":987203007,"bound_title":"De lachende politieman","reviewed_at":"2026-11-02T17:16:06+00:00","bound_isbn13":"9789044914399","evidence_url":"https://data.bibliotheken.nl/id/nbt/p043966454","review_batch":"nl-scale-20261102-004","review_status":"approved","bound_language":"dut","card_cover_url":"https://covers.openlibrary.org/b/id/14403489-M.jpg?default=false","bound_author_id":987303004},"before_row":null},{"key":{"native_identity_key":"nlscale:20261102:ol:OL2652815W"},"seq":43,"relation":"works","after_row":{"id":987103008,"title":"Trauma and Recovery","cover_id":12155135,"author_id":987303006,"work_type":null,"source_type":"open_library","open_library_id":"OL2652815W","first_publish_year":1992,"native_identity_key":"nlscale:20261102:ol:OL2652815W"},"before_row":null},{"key":{"open_library_edition_id":"OL9097054M"},"seq":44,"relation":"editions","after_row":{"id":987203008,"title":"Trauma en Herstel","isbn_10":null,"isbn_13":"9789028416536","work_id":987103008,"cover_id":12155135,"language":"dut","publisher":"Wereldbibliotheek","publish_date":null,"open_library_edition_id":"OL9097054M"},"before_row":null},{"key":{"work_id":987103008,"language":"nl"},"seq":45,"relation":"catalog_work_descriptions","after_row":{"text":"Judith Lewis Herman onderzoekt de gevolgen van ingrijpend geweld voor mensen die het ondergaan. Ze brengt ervaringen met mishandeling en seksueel geweld in verband met onderzoek naar oorlogservaringen en politieke terreur. Daarbij plaatst ze persoonlijke klachten en herstel in hun maatschappelijke omgeving. Het boek combineert onderzoek met getuigenissen en vraagt aandacht voor de positie van slachtoffers. De nadruk ligt op het begrijpen van overeenkomsten tussen ervaringen die vaak los van elkaar worden besproken.","work_id":987103008,"evidence":[{"note":"Exact Dutch original binding Trauma and Recovery1992, Judith Lewis Herman and9789028416536. Not the later Truth and Repair. New-edition afterwords, treatment promises and diagnostic traits are not applied to the old Dutch edition.","type":"reviewed_identity_and_bibliography","sources":["https://data.bibliotheken.nl/id/nbt/p11222931X","https://data.bibliotheken.nl/id/nbt/p394323904"],"reference":"new-work-dossier-readings-004.json#81","checked_at":"2026-11-02T17:16:06.000Z"},{"type":"original_substantive_source_review","review":"content-review-008.json","sources":["https://www.hbglibrary.com/titles/judith-lewis-herman-md/trauma-and-recovery/9781541602953/","https://catalog.williamjames.edu/bib/3288","https://openlibrary.org/works/OL2652815W","https://data.bibliotheken.nl/id/nbt/p11222931X","https://data.bibliotheken.nl/id/nbt/p394323904"]},{"type":"explicit_contributor_roles","credits":[],"limitation":