ie een bondgenoot is en wie hun plannen doorkruist.","work_id":987103009,"evidence":[{"note":"Separate Asterix and the Goths album, not Asterix and the Normans or the laurel-wreath album. KB Dutch ISBN9789032004620 and French1963 original agree. Script/art roles retained in evidence; no taste-test classification added.","type":"reviewed_identity_and_bibliography","sources":["https://data.bibliotheken.nl/id/nbt/p842260846"],"reference":"new-work-dossier-readings-004.json#82","checked_at":"2026-11-02T17:16:06.000Z"},{"type":"original_substantive_source_review","review":"content-amendment-001.json","sources":["https://www.hachette.co.uk/titles/ren%C3%A9-goscinny-2/asterix-asterix-and-the-goths/9780752866147/","https://openlibrary.org/works/OL267633W","https://data.bibliotheken.nl/id/nbt/p842260846"]},{"type":"explicit_contributor_roles","credits":[{"name":"Albert Uderzo","role":"original artist"}],"limitation":"Existing schema has one primary Work author; no synthetic combined-author identity or author merge."},{"type":"cover_front_review","sha256":"ab0d12f10fcbceac3f512a2a433dd8ae9872ff19f9be5aef1aa6b47d606cfb28","cover_id":13137509,"reference":"cover-semantic-review-003.json","limitation":"Front title/author and source-edition binding; no barcode or exact printing-year claim."}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://www.hachette.co.uk/titles/ren%C3%A9-goscinny-2/asterix-asterix-and-the-goths/9780752866147/","reviewed_at":"2026-11-02T17:16:06+00:00","source_name":"Gecontroleerde boek- en catalogusbronnen","source_type":"official_catalog","review_batch":"nl-scale-20261102-004","review_status":"approved","bound_author_id":987303005},"before_row":null},{"key":{"edition_id":987203009},"seq":50,"relation":"catalog_edition_metadata","after_row":{"format":"paperback","work_id":987103009,"evidence":[{"note":"Separate Asterix and the Goths album, not Asterix and the Normans or the laurel-wreath album. KB Dutch ISBN9789032004620 a