tie van commissaris Alba Díaz de Salvatierra krijgt een bedreigende betekenis. Terwijl hij verbanden probeert te leggen, moet hij voorkomen dat het rituele patroon zich voortzet.","work_id":987103013,"evidence":[{"note":"Los ritos del agua/De riten van het water is distinct from current El silencio de la ciudad blanca. Publisher content and separately listed paperback9789400514133 plus KB exact original2017 agree. EbookISBN is content evidence, not the proposed print identity.","type":"reviewed_identity_and_bibliography","sources":["https://data.bibliotheken.nl/id/nbt/p432152105"],"reference":"new-work-dossier-readings-004.json#116","checked_at":"2026-11-02T17:16:06.000Z"},{"type":"original_substantive_source_review","review":"content-review-009.json","sources":["https://www.awbruna.nl/boek/thrillers/eva-garcia-saenz-de-urturi/de-riten-van-het-water/ebook/9789044978377/","https://data.bibliotheken.nl/id/nbt/p432152105"]},{"type":"explicit_contributor_roles","credits":[],"limitation":"Existing schema has one primary Work author; no synthetic combined-author identity or author merge."},{"type":"cover_front_review","sha256":"7e04b140da2abab9a2346a127de1ce9cfd5cbf67d6354648997fb79e40747cd0","cover_id":13012233,"reference":"cover-semantic-review-002.json","limitation":"Front title/author and source-edition binding; no barcode or exact printing-year claim."}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://www.awbruna.nl/boek/thrillers/eva-garcia-saenz-de-urturi/de-riten-van-het-water/ebook/9789044978377/","reviewed_at":"2026-11-02T17:16:06+00:00","source_name":"Gecontroleerde boek- en catalogusbronnen","source_type":"official_catalog","review_batch":"nl-scale-20261102-004","review_status":"approved","bound_author_id":987303009},"before_row":null},{"key":{"edition_id":987203013},"seq":66,"relation":"catalog_edition_metadata","after_row":{"format":"paperback","work_id":987103013,"evidence":[{"note":"Los ritos del agua/De riten van het 