n_library_edition_id":"OL26805002M"},"seq":68,"relation":"editions","after_row":{"id":987203014,"title":"De mysterieuze zolder","isbn_10":null,"isbn_13":"9789000339259","work_id":987103014,"cover_id":8459679,"language":"dut","publisher":"UNIEBOEK | HET SPECTRUM","publish_date":null,"open_library_edition_id":"OL26805002M"},"before_row":null},{"key":{"work_id":987103014,"language":"nl"},"seq":69,"relation":"catalog_work_descriptions","after_row":{"text":"Na een brand verhuist Nick met zijn vader en broertje naar een geërfd oud huis. Op zolder liggen voorwerpen die aanvankelijk waardeloze rommel lijken. Pas nadat hij ze heeft verkocht, ontdekken Nick en zijn vrienden dat ze bijzondere eigenschappen hebben. De spullen blijken samen te hangen met uitvinder Nikola Tesla en met een gevaarlijk plan. Terwijl ze proberen te begrijpen wat er is gebeurd, trekt ook de zolder zelf steeds meer onverklaarbare problemen aan.","work_id":987103014,"evidence":[{"note":"Tesla''s Attic/De mysterieuze zolder is Accelerati book1, distinct from captured Scythe, Unwind, Everlost and Antsy novels. Bureau ISBN exact hardcover9789000339259 explicitly credits both authors; Rozet confirms original2014 and Dutch print. Page count varies by source and is not imported.","type":"reviewed_identity_and_bibliography","sources":["https://data.bibliotheken.nl/id/nbt/p373735413"],"reference":"new-work-dossier-readings-004.json#133","checked_at":"2026-11-02T17:16:06.000Z"},{"type":"original_substantive_source_review","review":"content-review-010.json","sources":["https://metadata.isbn.nl/505339/de-mysterieuze-zolder.html","https://rozet.nl/catalogus/1483503/","https://books.disney.com/content/uploads/2014/01/Teslas-Attic-DG-%C2%A6%C3%86.pdf","https://openlibrary.org/works/OL15547922W","https://data.bibliotheken.nl/id/nbt/p373735413"]},{"type":"explicit_contributor_roles","credits":[{"name":"Eric Elfman","role":"joint original author"},{"name":"Wiebe Buddingh''","role":"Dutch translator"},{"name":"Wouter Tul