liger Jane Webster een verontrustend telefoontje. Ze weet niet of de beller de waarheid spreekt en worstelt met de vertrouwelijkheid van haar werk. Wat zij hoort, zou het vastgelopen onderzoek een nieuwe richting kunnen geven.","work_id":987103015,"evidence":[{"note":"The Nightmare Place/Duister oord is distinct from current Still Bleeding, Cry for Help and The Whisper Man. Exact KB original Orion2014 and Dutch ISBN match Steve Mosby credit and front. Do not rename all existing Mosby Works because he also uses Alex North.","type":"reviewed_identity_and_bibliography","sources":["https://data.bibliotheken.nl/id/nbt/p376323159"],"reference":"new-work-dossier-readings-004.json#137","checked_at":"2026-11-02T17:16:06.000Z"},{"type":"original_substantive_source_review","review":"content-review-010.json","sources":["https://openlibrary.org/works/OL17485749W","https://data.bibliotheken.nl/id/nbt/p376323159"]},{"type":"explicit_contributor_roles","credits":[],"limitation":"Existing schema has one primary Work author; no synthetic combined-author identity or author merge."},{"type":"cover_front_review","sha256":"bfe138d68fc9413b8b902bf695930fc76d6b75c537560c1e50b8d64ae3d45611","cover_id":12159335,"reference":"cover-semantic-review-002.json","limitation":"Front title/author and source-edition binding; no barcode or exact printing-year claim."}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://openlibrary.org/works/OL17485749W","reviewed_at":"2026-11-02T17:16:06+00:00","source_name":"Gecontroleerde boek- en catalogusbronnen","source_type":"official_catalog","review_batch":"nl-scale-20261102-004","review_status":"approved","bound_author_id":946301516},"before_row":null},{"key":{"edition_id":987203015},"seq":74,"relation":"catalog_edition_metadata","after_row":{"format":"paperback","work_id":987103015,"evidence":[{"note":"The Nightmare Place/Duister oord is distinct from current Still Bleeding, Cry for Help and The Whisper Man. Exact KB origina