n_id":"OL12804334M"},"before_row":null},{"key":{"work_id":987103018,"language":"nl"},"seq":85,"relation":"catalog_work_descriptions","after_row":{"text":"Lorenzo Brown heeft na zijn gevangenisstraf werk gevonden bij een dierenbeschermingsorganisatie. Het verzorgen en beschermen van honden helpt hem afstand te houden van zijn oude bestaan. Zijn reclasseringsambtenaar Rachel Lopez probeert anderen vooruit te helpen, maar heeft zelf steeds meer moeite overeind te blijven. Wanneer spanningen op straat dreigen uit te lopen op geweld, heeft Lorenzo haar steun harder nodig dan ooit. Hun levens raken verbonden door de vraag hoe kwetsbaar een nieuwe start kan zijn.","work_id":987103018,"evidence":[{"note":"Drama City/Drama stad and the reintegration premise differ from current The Night Gardener. KB originalLittleBrown2005, George P. Pelecanos, Dutch ISBN9789041409621 and bound cover agree.","type":"reviewed_identity_and_bibliography","sources":["https://data.bibliotheken.nl/id/nbt/p282375317"],"reference":"new-work-dossier-readings-004.json#142","checked_at":"2026-11-02T17:16:06.000Z"},{"type":"original_substantive_source_review","review":"content-review-010.json","sources":["https://openlibrary.org/works/OL23557W","https://data.bibliotheken.nl/id/nbt/p282375317"]},{"type":"explicit_contributor_roles","credits":[],"limitation":"Existing schema has one primary Work author; no synthetic combined-author identity or author merge."},{"type":"cover_front_review","sha256":"dbbcc0612e93a9570cb77bd8924b34f0b67023b3eac82d3e0326b1dfe42aceb9","cover_id":9189612,"reference":"cover-semantic-review-002.json","limitation":"Front title/author and source-edition binding; no barcode or exact printing-year claim."}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://openlibrary.org/works/OL23557W","reviewed_at":"2026-11-02T17:16:06+00:00","source_name":"Gecontroleerde boek- en catalogusbronnen","source_type":"official_catalog","review_batch":"nl-scale-20261102-004","review_status":"approved","bound_author_id":987303012},"before_row":null},{"key":{"edition_id":987203018},"seq":86,"relation":"catalog_edition_metadata","after_row":{"format":"paperback","work_id":987103018,"evidence":[{"note":"Drama City/Drama stad and the reintegration premise differ from current The Night Gardener. KB originalLittleBrown2005, George P. Pelecanos, Dutch ISBN9789041409621 and bound cover agree.","type":"reviewed_identity_and_bibliography","sources":["https://data.bibliotheken.nl/id/nbt/p282375317"],"reference":"new-work-dossier-readings-004.json#142","checked_at":"2026-11-02T17:16:06.000Z"},{"type":"original_substantive_source_review","review":"content-review-010.json","sources":["https://openlibrary.org/works/OL23557W","https://data.bibliotheken.nl/id/nbt/p282375317"]},{"type":"explicit_contributor_roles","credits":[],"limitation":"Existing schema has one primary Work author; no synthetic combined-author identity or author merge."},{"type":"cover_front_review","sha256":"dbbcc0612e93a9570cb77bd8924b34f0b67023b3eac82d3e0326b1dfe42aceb9","cover_id":9189612,"reference":"cover-semantic-review-002.json","limitation":"Front title/author and source-edition binding; no barcode or exact printing-year claim."}],"cover_url":"https://covers.openlibrary.org/b/id/9189612-L.jpg?default=false","edition_id":987203018,"bound_title":"Drama Stad","reviewed_at":"2026-11-02T17:16:06+00:00","bound_isbn13":"9789041409621","evidence_url":"https://data.bibliotheken.nl/id/nbt/p282375317","review_batch":"nl-scale-20261102-004","review_status":"approved","bound_language":"dut","card_cover_url":"https://covers.openlibrary.org/b/id/9189612-M.jpg?default=false","bound_author_id":987303012},"before_row":null},{"key":{"native_identity_key":"nlscale:20261102:ol:OL30590560W"},"seq":87,"relation":"works","after_row":{"id":987103019,"title":"Belgische republikeinen","cover_id":14234466,"author_id":987303013,"work_type":null,"source_type":"open_library","open_library_id":"OL30590560W","first_publish_year":2020,"native_identity_key":"nlscale:20261102:ol:OL30590560W"},"before_row":null},{"key":{"open_library_edition_id":"OL42056676M"},"seq":88,"relation":"editions","after_row":{"id":987203019,"title":"Belgische republikeinen","isbn_10":null,"isbn_13":"9789463105071","work_id":987103019,"cover_id":14234466,"language":"dut","publisher":"Pelckmans / Uitgeverij Polis","publish_date":null,"open_library_edition_id":"OL42056676M"},"before_row":null},{"key":{"work_id":987103019,"language":"nl"},"seq":89,"relation":"catalog_work_descriptions","after_row":{"text":"Els Witte onderzoekt de Belgische republikeinen die tijdens en na de revolutie van 1830 voor een andere staatsvorm streden. Zij wilden democratische rechten en een republiek, maar zagen hoe liberalen en katholieken binnen een monarchie de macht verdeelden. Het boek volgt hun verzet, hun onderlinge strijd en hun uiteindelijke marginalisering. Daarbij wordt duidelijk welke plaats deze radicale stroming innam in het ontstaan van België en hoe haar denkbeelden later bleven doorwerken.","work_id":987103019,"evidence":[{"note":"Els Witte''s study of Belgian republicans1830–1850 is different from current Het verloren koninkrijk. ExactKB Dutch title/author/ISBN and scholarly university2020 bibliography agree. Historical nonfiction, no invented fiction or taste attributes.","type":"reviewed_identity_and_bibliography","sources":["https://data.bibliotheken.nl/id/nbt/p426507843"],"reference":"new-work-dossier-readings-004.json#145","checked_at":"2026-11-02T17:16:06.000Z"},{"type":"original_substantive_source_review","review":"content-review-010.json","sources":["https://rechtsgeschiedenis.ugent.be/courant/2020/202002/202002%20Courant%20Februari.pdf","https://openlibrary.org/works/OL30590560W","https://data.bibliotheken.nl/id/nbt/p426507843"]},{"type":"explicit_contributor_roles","credits":[],"limitation":"Existing schema has one primary Work author; no synthetic combined-author identity or author merge.