laim."}],"cover_url":"https://covers.openlibrary.org/b/id/14234466-L.jpg?default=false","edition_id":987203019,"bound_title":"Belgische republikeinen","reviewed_at":"2026-11-02T17:16:06+00:00","bound_isbn13":"9789463105071","evidence_url":"https://data.bibliotheken.nl/id/nbt/p426507843","review_batch":"nl-scale-20261102-004","review_status":"approved","bound_language":"dut","card_cover_url":"https://covers.openlibrary.org/b/id/14234466-M.jpg?default=false","bound_author_id":987303013},"before_row":null},{"key":{"native_identity_key":"nlscale:20261102:ol:OL20293310W"},"seq":91,"relation":"works","after_row":{"id":987103020,"title":"De stilte van het licht","cover_id":8951874,"author_id":987303014,"work_type":null,"source_type":"open_library","open_library_id":"OL20293310W","first_publish_year":2015,"native_identity_key":"nlscale:20261102:ol:OL20293310W"},"before_row":null},{"key":{"open_library_edition_id":"OL27494557M"},"seq":92,"relation":"editions","after_row":{"id":987203020,"title":"De stilte van het licht","isbn_10":null,"isbn_13":"9789029589888","work_id":987103020,"cover_id":8951874,"language":"dut","publisher":"De Arbeiderspers","publish_date":null,"open_library_edition_id":"OL27494557M"},"before_row":null},{"key":{"work_id":987103020,"language":"nl"},"seq":93,"relation":"catalog_work_descriptions","after_row":{"text":"Joost Zwagerman onderzoekt hoe beeldende kunst een ervaring van stilte kan oproepen. Hij kijkt naar uiteenlopende kunstenaars, van oude meesters tot abstracte schilders en Edward Hopper. Licht speelt daarbij telkens een andere rol: het kan verstilling scheppen, ruimte openen of juist spanning oproepen. De essays verbinden aandachtig kijken met reflecties op een wereld vol beelden. Het boek vraagt hoe een kunstwerk rust en intensiteit tegelijk kan laten ervaren zonder dat stilte eenvoudig afwezigheid wordt.","work_id":987103020,"evidence":[{"note":"Joost Zwagerman''s art essays differ from captured Americana and Duel. Full NTA name Johannes Jac